import pathlib,json,hashlib,re
E=pathlib.Path('reviews/evidence/M1-C1.4-r5')
r=json.loads((E/'receipt.json').read_text())
assert len(r['status'])==5 and not any(r['status'].values())
for p,h in r['sha256'].items(): assert hashlib.sha256((E/p).read_bytes()).hexdigest()==h,p
s=(E/'gates/test.log').read_text(); a=re.findall(r'test result: ok\. (\d+) passed; (\d+) failed; (\d+) ignored',s)
assert [sum(int(x[i]) for x in a) for i in range(3)]==[716,0,5]
for n in ['wire_module_is_current','model_module_is_current','commands_module_is_current']: assert n+' ... ok' in s
sdk=(E/'gates/mcp-conformance.log').read_text(); assert '"passed": 24' in sdk and '"failed": 0' in sdk
print('Local receipt: five zero statuses;',len(r['sha256']),'hashes match; workspace 716/0/5; IPC freshness and SDK 24/24 pass.')
p=pathlib.Path('reviews/M1-C1.4-r5-closure.md');s=p.read_text(encoding='utf-8-sig')
s=s.replace('**Verdict: pending local regression sweep.** C14-R4-01 closes in the targeted probes; the full local sweep is running.','**Verdict: pass.** C14-R4-01 is closed as ruled, and the scoped regression sweep passes. The M1 merge gate is satisfied within the retained owner dispositions and accepted limits.')
s=s.replace('Local sweep results will be finalized after completion.','Local `cargo test --workspace --locked --no-fail-fast` exits 0: **716 passed / 0 failed / 5 ignored** across 122 result summaries. The workspace run discovered targets before the new r5 file was added; those four probes pass separately (4/4), as do the unchanged r4 probes (4/4). No counts are double-counted. `pnpm test` exits 0: **333/333 in 40 files plus 9/9 tooling tests**. The declaration gate regenerates 662 declarations without diff and verifies **98 allow entries in 40 product files, 0 new, 0 removed**. All three Rust-generated frontend/IPC freshness tests pass. The release headless build, two compared self-tests and linked-library/dependency check pass; local official Python SDK conformance passes **24/24**. [Local receipt](evidence/M1-C1.4-r5/receipt.json) records five selected gates, all zero; its eight hashes match. This is a scoped local rerun, separate from the verified 18-gate builder receipt. New reviewer probes also pass clippy with warnings denied. [Local verification](evidence/M1-C1.4-r5/local-verification.log), [ignored-body verification](evidence/M1-C1.4-r5/ignored-verification.log). The two named self-rewriting C1.3 evidence files were restored from git before the final commit; product and frozen spec files remain untouched.')
s=s.replace('#M1-merge-readiness','#m1-merge-readiness')
s=s.replace('Final M1 merge statement will be finalized with the local sweep.','The orchestrator may merge the reviewed M1 implementation at `e2eba79` together with this reviewer branch, retain the closure probes and evidence, and tag M1 under the recorded interim rulings. This pass certifies the scoped C14-R4-01 closure and the requested regression gates; it does not certify a ratified newer MCP protocol target (SI-049), attached-host support, deferred M2+ functionality, the retained performance limits, arbitrary-export crash/ACL/late-root scenarios, network filesystem durability, or real-device/manual macOS QA. Those remain with the owners and deadlines in the retained readiness list. This review creates no merge, tag or GitHub issue.')
p.write_text(s,encoding='utf-8')
